function kindOf(value) {
  if (value === null) {
    return 'null';
  }
  if (Array.isArray(value)) {
    return 'array';
  }
  return typeof value;
}

function isPrimitive(value) {
  if (value === null) {
    return true;
  }
  return typeof value !== 'object' && typeof value !== 'function';
}

console.log(kindOf(null), kindOf([1]), kindOf({}), kindOf(1n));
console.log(isPrimitive('a'), isPrimitive(null), isPrimitive([]), isPrimitive(function () {}));

