function memoize(fn) {
  const cache = {};
  return function (n) {
    if (cache[n] !== undefined) {
      return cache[n];
    }
    const result = fn(n);
    cache[n] = result;
    return result;
  };
}

let calls = 0;
function slowSquare(n) {
  calls += 1;
  return n * n;
}

const fastSquare = memoize(slowSquare);
