function reduce(list, callback, ...rest) {
  let i = 0;
  let acc;
  if (rest.length > 0) {
    acc = rest[0];
  } else if (list.length > 0) {
    acc = list[0];
    i = 1;
  } else {
    throw new TypeError('Reduce of empty array with no initial value');
  }
  for (; i < list.length; i++) {
    acc = callback(acc, list[i], i, list);
  }
  return acc;
}

console.log(reduce([3, 5, 2], (acc, x) => acc + x, 0)); // 10
console.log(reduce([3, 5, 2], (acc, x) => acc + x)); // 10
console.log(reduce([], (acc, x) => acc + x, 'пусто')); // пусто

