const sizes = new WeakMap();
let calls = 0;

function folderSize(folder) {
  if (sizes.has(folder)) return sizes.get(folder);
  calls++;
  const size = folder.files.reduce((sum, file) => sum + file.size, 0);
  sizes.set(folder, size);
  return size;
}

const docs = { files: [{ size: 10 }, { size: 32 }] };
