console.log(folderSize(docs)); // 42
console.log(calls); // 1

const balances = new WeakMap();

class Wallet {
  constructor() {
    balances.set(this, 0);
  }
  deposit(sum) {
    balances.set(this, balances.get(this) + sum);
    return this;
  }
  get balance() {
    return balances.get(this);
  }
}

