function makeCache(compute) {
  const refs = new Map();
  return function get(key) {
    const cached = refs.get(key)?.deref();
    if (cached !== undefined) return cached;
    const value = compute(key);
    refs.set(key, new WeakRef(value));
    return value;
  };
}

const loadImage = makeCache((url) => ({ url, pixels: new Array(1000).fill(0) }));
const first = loadImage('cat.png');
console.log(loadImage('cat.png') === first); // true

const refs = new Map();
const registry = new FinalizationRegistry((key) => {
  if (refs.get(key)?.deref() === undefined) refs.delete(key);
});

function remember(key, value) {
  refs.set(key, new WeakRef(value));
  registry.register(value, key);
}

