function track(target, passReceiver) {
  const reads = [];
  const proxy = new Proxy(target, {
    get(t, key, receiver) {
      reads.push(String(key));
      return passReceiver ? Reflect.get(t, key, receiver) : t[key];
    },
  });
  return { proxy, reads };
}

