const bar = document.querySelector('#progress');
const duration = 1000; // полоса заполнится за 1 секунду
let start = null;

function frame(time) {
  start ??= time;
  const progress = Math.min((time - start) / duration, 1);
  bar.style.width = `${progress * 100}%`;
  if (progress < 1) requestAnimationFrame(frame); // попросить следующий кадр
}

requestAnimationFrame(frame);

function processInChunks(items, handle, onDone, chunkSize = 10_000) {
  let index = 0;
  let chunks = 0;

  function nextChunk() {
    const end = Math.min(index + chunkSize, items.length);
    for (; index < end; index += 1) {
      handle(items[index]);
    }
    chunks += 1;
    if (index < items.length) {
      setTimeout(nextChunk, 0); // отдаём поток до следующего куска
    } else {
      onDone(chunks);
    }
  }

  nextChunk();
}

const items = Array.from({ length: 100_000 }, (_, i) => i);
