function debounce(fn, ms) {
  let timerId;
  return function (...args) {
    clearTimeout(timerId); // новое событие отменяет запланированный вызов
    timerId = setTimeout(() => fn.apply(this, args), ms);
  };
}

function throttle(fn, ms) {
  let last = 0;
  return function (...args) {
    const now = Date.now();
    if (now - last >= ms) {
      last = now;
      fn.apply(this, args);
    }
  };
}

