const finished = [];
const task = (name, ms, ok = true) =>
  new Promise((resolve, reject) => {
    setTimeout(() => {
      finished.push(name);
      if (ok) {
        resolve(name);
      } else {
        reject(new Error(name));
      }
    }, ms);
  });

Promise.all([
  task('медленная', 40),
  task('сломанная', 10, false),
  task('быстрая', 20),
])
  .then((values) => console.log('все:', values))
  .catch((e) => {
    console.log('отклонён:', e.message, '| готовы:', finished.join(', '));
  });
setTimeout(() => console.log('через 60 мс:', finished.join(', ')), 60);

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
